import{_ as a,o,c as r,ae as i}from"./chunks/framework.Co1PSFSm.js";const h=JSON.parse('{"title":"Manual de Operación: Restore Wizard","description":"","frontmatter":{},"headers":[],"relativePath":"guides/restore.md","filePath":"guides/restore.md"}'),n={name:"guides/restore.md"};function s(l,e,t,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="manual-de-operacion-restore-wizard" tabindex="-1">Manual de Operación: Restore Wizard <a class="header-anchor" href="#manual-de-operacion-restore-wizard" aria-label="Permalink to &quot;Manual de Operación: Restore Wizard&quot;">​</a></h1><p>El nuevo <strong>Asistente de Restauración Avanzada</strong> permite recuperaciones granulares con precisión quirúrgica, sin necesidad de restaurar el servidor completo si solo quieres un archivo.</p><h2 id="jerarquia-de-recuperacion" tabindex="-1">Jerarquía de Recuperación <a class="header-anchor" href="#jerarquia-de-recuperacion" aria-label="Permalink to &quot;Jerarquía de Recuperación&quot;">​</a></h2><p>El sistema organiza los puntos de restauración en tres niveles de profundidad:</p><ol><li><strong>Día (Calendario):</strong> Selección de la fecha en la que existía el dato deseado.</li><li><strong>Hora (Snapshot):</strong> Selección del momento exacto del día (útil si se realizaron múltiples respaldos manuales o automáticos).</li><li><strong>Contenido (Granular):</strong> Exploración de las carpetas internas del respaldo para recuperar solo lo necesario.</li></ol><h2 id="flujo-de-trabajo-del-wizard" tabindex="-1">Flujo de Trabajo del Wizard <a class="header-anchor" href="#flujo-de-trabajo-del-wizard" aria-label="Permalink to &quot;Flujo de Trabajo del Wizard&quot;">​</a></h2><h3 id="_1-seleccion-de-punto-de-control" tabindex="-1">1. Selección de Punto de Control <a class="header-anchor" href="#_1-seleccion-de-punto-de-control" aria-label="Permalink to &quot;1. Selección de Punto de Control&quot;">​</a></h3><ul><li>Al abrir el wizard desde el dashboard, el sistema agrupa los IDs de snapshot por fecha.</li><li>El usuario selecciona el día y luego la hora específica de la lista desplegable.</li></ul><h3 id="_2-exploracion-del-snapshot" tabindex="-1">2. Exploración del Snapshot <a class="header-anchor" href="#_2-exploracion-del-snapshot" aria-label="Permalink to &quot;2. Exploración del Snapshot&quot;">​</a></h3><ul><li>El agente ejecuta <code>restic ls &lt;id&gt;</code> en segundo plano.</li><li>El usuario selecciona qué carpetas o archivos desea restaurar (ej: Solo la base de datos <code>/database</code> o solo el código <code>/public_html</code>).</li></ul><h3 id="_3-configuracion-del-destino" tabindex="-1">3. Configuración del Destino <a class="header-anchor" href="#_3-configuracion-del-destino" aria-label="Permalink to &quot;3. Configuración del Destino&quot;">​</a></h3><ul><li>Se define un <strong>Path de Recuperación</strong> (por defecto <code>/restore_data</code>).</li><li>El sistema descargará únicamente los archivos seleccionados, ahorrando tiempo y ancho de banda.</li><li><strong>Auto-Up:</strong> Si está activado, el agente intentará levantar los servicios Docker restaurados.</li></ul><h2 id="consideraciones-de-rendimiento" tabindex="-1">Consideraciones de Rendimiento <a class="header-anchor" href="#consideraciones-de-rendimiento" aria-label="Permalink to &quot;Consideraciones de Rendimiento&quot;">​</a></h2><ul><li><strong>Carga de Índices:</strong> Explorar snapshots muy grandes (+500GB) puede tardar unos segundos mientras el agente descarga la estructura.</li><li><strong>Seguridad:</strong> Los archivos restaurados mantienen sus permisos originales de Linux.</li><li><strong>Espacio en Disco:</strong> Asegúrate de tener suficiente espacio en el host para el volcado de datos.</li></ul>',14)])])}const g=a(n,[["render",s]]);export{h as __pageData,g as default};
